<template><section class="section-card"><h2 class="section-title">Subscription renewal simulator</h2><div class="section-body"><p class="field-help">Review only. Expire the current period first, then submit a simulated billing event. This does not contact a store.</p><el-select v-model="outcome"><el-option label="Renewal payment succeeds" value="succeeded"/><el-option label="Renewal payment fails" value="failed"/></el-select><div v-for="subscription in subscriptions" :key="subscription.id"><p>{{ subscription.productName }} · {{ subscription.status }} · {{ subscription.pendingChange?'change scheduled':'no pending change' }}</p><el-button :disabled="busy || subscription.grant.status!=='expired' || !subscription.autoRenew" @click="run(subscription)">Simulate renewal event</el-button></div><p v-if="error" class="inline-error">{{ error }}</p></div></section></template>
<script>
import {renewDemo,requestKey} from '@/api/commerce'
export default{props:{subscriptions:Array},data(){return{busy:false,outcome:'succeeded',error:''}},methods:{async run(subscription){this.busy=true;try{await renewDemo(subscription.id,{periodEnd:subscription.grant.expiresAt,outcome:this.outcome,requestKey:requestKey()});this.error='';this.$emit('changed')}catch(e){this.error=e.message}finally{this.busy=false}}}}
</script>
